import React from "react";
import Grid from "@material-ui/core/Grid";
import "../assets/css/titleBar.css";

function TitleBar(props) {
  return (
    <Grid container direction="col" justify="center" alignItems="center">
      <Grid
        item
        container
        direction="row"
        justify="space-around"
        alignItems="center"
      >
        <button
          item
          className="buttonsButton like-link homeButton hover-underline"
          href="/"
        >
          <h1 className="montserrat-medium fs-2rem">home</h1>
        </button>
      </Grid>
      {props.title ? (
        <h1 item id="title" className="montserrat-medium">
          {props.title}
        </h1>
      ) : null}
    </Grid>
  );
